CREATE OR REPLACE FUNCTION public.crm_normalize_contact_phones_trigger()
RETURNS trigger LANGUAGE plpgsql SET search_path TO '' AS $$
DECLARE row_data jsonb:=to_jsonb(NEW);dial text;local_phone text;normalized text;
BEGIN
 IF row_data ? 'telephone' THEN dial:=nullif(trim(row_data->>'telephone_indicatif'),'');local_phone:=nullif(trim(row_data->>'telephone_local'),'');normalized:=public.crm_normalize_phone_e164(COALESCE(local_phone,row_data->>'telephone'),dial);IF normalized IS NOT NULL THEN row_data:=jsonb_set(row_data,'{telephone}',to_jsonb(normalized),true);END IF;END IF;
 IF row_data ? 'telephone_secondaire' THEN dial:=nullif(trim(row_data->>'telephone_secondaire_indicatif'),'');local_phone:=nullif(trim(row_data->>'telephone_secondaire_local'),'');normalized:=public.crm_normalize_phone_e164(COALESCE(local_phone,row_data->>'telephone_secondaire'),dial);IF normalized IS NOT NULL THEN row_data:=jsonb_set(row_data,'{telephone_secondaire}',to_jsonb(normalized),true);END IF;END IF;
 IF row_data ? 'whatsapp' THEN dial:=nullif(trim(row_data->>'whatsapp_indicatif'),'');local_phone:=nullif(trim(row_data->>'whatsapp_local'),'');normalized:=public.crm_normalize_phone_e164(COALESCE(local_phone,row_data->>'whatsapp'),dial);IF normalized IS NOT NULL THEN row_data:=jsonb_set(row_data,'{whatsapp}',to_jsonb(normalized),true);END IF;END IF;
 IF row_data ? 'phone' THEN normalized:=public.crm_normalize_phone_e164(row_data->>'phone',NULL);IF normalized IS NOT NULL THEN row_data:=jsonb_set(row_data,'{phone}',to_jsonb(normalized),true);END IF;END IF;
 IF row_data ? 'secondary_phone' THEN normalized:=public.crm_normalize_phone_e164(row_data->>'secondary_phone',NULL);IF normalized IS NOT NULL THEN row_data:=jsonb_set(row_data,'{secondary_phone}',to_jsonb(normalized),true);END IF;END IF;
 NEW:=jsonb_populate_record(NEW,row_data);RETURN NEW;
END;$$;
DROP TRIGGER IF EXISTS trg_crm_normalize_contact_phones ON public.imported_phone_contacts;
CREATE TRIGGER trg_crm_normalize_contact_phones BEFORE INSERT OR UPDATE ON public.imported_phone_contacts FOR EACH ROW EXECUTE FUNCTION public.crm_normalize_contact_phones_trigger();
UPDATE public.clients SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone_local,telephone_indicatif),public.crm_normalize_phone_e164(telephone,telephone_indicatif),telephone),telephone_secondaire=COALESCE(public.crm_normalize_phone_e164(telephone_secondaire_local,telephone_secondaire_indicatif),public.crm_normalize_phone_e164(telephone_secondaire,telephone_secondaire_indicatif),telephone_secondaire),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp_local,whatsapp_indicatif),public.crm_normalize_phone_e164(whatsapp,whatsapp_indicatif),whatsapp);
UPDATE public.leads SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone,NULL),telephone),telephone_secondaire=COALESCE(public.crm_normalize_phone_e164(telephone_secondaire,telephone_secondaire_indicatif),telephone_secondaire),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp,NULL),whatsapp);
UPDATE public.prospects SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone,NULL),telephone),telephone_secondaire=COALESCE(public.crm_normalize_phone_e164(telephone_secondaire,telephone_secondaire_indicatif),telephone_secondaire),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp,NULL),whatsapp);
UPDATE public.proprietaires_terres SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone_local,telephone_indicatif),public.crm_normalize_phone_e164(telephone,telephone_indicatif),telephone),telephone_secondaire=COALESCE(public.crm_normalize_phone_e164(telephone_secondaire_local,telephone_secondaire_indicatif),public.crm_normalize_phone_e164(telephone_secondaire,telephone_secondaire_indicatif),telephone_secondaire),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp_local,whatsapp_indicatif),public.crm_normalize_phone_e164(whatsapp,whatsapp_indicatif),whatsapp);
UPDATE public.profiles SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone_local,telephone_indicatif),public.crm_normalize_phone_e164(telephone,telephone_indicatif),telephone),telephone_secondaire=COALESCE(public.crm_normalize_phone_e164(telephone_secondaire_local,telephone_secondaire_indicatif),public.crm_normalize_phone_e164(telephone_secondaire,telephone_secondaire_indicatif),telephone_secondaire),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp_local,whatsapp_indicatif),public.crm_normalize_phone_e164(whatsapp,whatsapp_indicatif),whatsapp);
UPDATE public.crm_parties SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone,NULL),telephone),telephone_secondaire=COALESCE(public.crm_normalize_phone_e164(telephone_secondaire,NULL),telephone_secondaire),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp,NULL),whatsapp);
UPDATE public.cotitulaires_mandataires SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone,NULL),telephone),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp,NULL),whatsapp);
UPDATE public.client_cotitulaires_mandataires SET telephone=COALESCE(public.crm_normalize_phone_e164(telephone_local,telephone_indicatif),public.crm_normalize_phone_e164(telephone,telephone_indicatif),telephone),whatsapp=COALESCE(public.crm_normalize_phone_e164(whatsapp_local,whatsapp_indicatif),public.crm_normalize_phone_e164(whatsapp,whatsapp_indicatif),whatsapp);
UPDATE public.imported_phone_contacts SET phone=COALESCE(public.crm_normalize_phone_e164(phone,NULL),phone),secondary_phone=COALESCE(public.crm_normalize_phone_e164(secondary_phone,NULL),secondary_phone);